mapper.select:
SELECT *
FROM device_info


        AND (
            device_info_name LIKE CONCAT('%', #{q.keyword}, '%')
            OR device_info_code LIKE CONCAT('%', #{q.keyword}, '%')
            OR device_info_ip LIKE CONCAT('%', #{q.keyword}, '%')
            OR device_info_serial LIKE CONCAT('%', #{q.keyword}, '%')
            OR device_info_owner_name LIKE CONCAT('%', #{q.keyword}, '%')
        )


        AND device_info_org_id = #{q.orgId}


        AND device_info_vendor = #{q.vendor}


        AND device_info_category = #{q.category}


        AND device_info_sub_category = #{q.subCategory}


        AND device_info_online = #{q.online}


        AND device_info_status = #{q.status}


        AND device_info_owner_id = #{q.ownerId}


        AND device_info_tags LIKE CONCAT('%', #{q.tag}, '%')


ORDER BY

    device_info_name
    device_info_created_at
    device_info_last_online_at
    device_info_updated_at


    ASC
    DESC

SELECT COUNT(*) AS total, COUNT(CASE WHEN device_info_online = 1 THEN 1 END) AS online, COUNT(CASE WHEN device_info_online = 0 OR device_info_online IS NULL THEN 1 END) AS offline, COUNT(CASE WHEN device_info_latitude IS NULL OR device_info_longitude IS NULL OR device_info_latitude = 0 OR device_info_longitude = 0 THEN 1 END) AS no_location FROM device_info
AND device_info_org_id = #{orgId}
AND device_info_vendor = #{vendor}
